/** Prove mismatch control red on a generated copy; never mutate application files. */
import { mkdtemp, readFile, writeFile, rm } from 'node:fs/promises';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { createHash } from 'node:crypto';
import { spawnSync } from 'node:child_process';
const evidence=dirname(fileURLToPath(import.meta.url));
const repo=resolve(evidence,'../../../..');
const sourcePath=resolve(repo,'server/services/advancedRAGPipeline.ts');
const source=await readFile(sourcePath,'utf8');
const hash=bytes=>createHash('sha256').update(bytes).digest('hex');
const needle='    assertVaultSourceScope(read, source);';
if(source.split(needle).length!==2)throw new Error('Expected one immutable-scope identity checkpoint');
const variant=source.replace(needle,'    // Counterfactual: identity checkpoint intentionally omitted.').replace(
  /(from\s+['"]|import\(['"])(\.{1,2}\/[^'"]+)(['"])/g,
  (_all,start,spec,end)=>start+resolve(dirname(sourcePath),spec)+end,
);
const tmp=await mkdtemp(resolve(evidence,'.recall-counterfactual-'));
try{
  const copy=resolve(tmp,'pipeline.ts');await writeFile(copy,variant);
  const config=resolve(tmp,'config.mts');
  await writeFile(config,`import {defineConfig} from 'vitest/config';\nexport default defineConfig({root:${JSON.stringify(repo)},resolve:{alias:[{find:'../../../../server/services/advancedRAGPipeline.ts',replacement:${JSON.stringify(copy)}},{find:'shared',replacement:${JSON.stringify(resolve(repo,'shared'))}}]},test:{environment:'node',include:['docs/evidence/D2-CANONICAL-PUBLICATION/2026-10-14/recall-rag-integration.test.mts'],pool:'forks',maxWorkers:1,fileParallelism:false,reporters:['verbose']}});\n`);
  const run=spawnSync(process.execPath,[resolve(repo,'node_modules/vitest/vitest.mjs'),'run','--config',config,'--testNamePattern','refuses mismatched source actor'],{cwd:repo,encoding:'utf8',env:process.env});
  const output=(run.stdout??'')+(run.stderr??'');await writeFile(resolve(evidence,'recall-rag-counterfactual-red.txt'),output);
  const after=await readFile(sourcePath,'utf8');
  const expected=run.status===1&&output.includes('promise resolved')&&output.includes('refuses mismatched source actor');
  const result={control:'source actor identity mismatch before embedding',mutation:'omit assertVaultSourceScope only in generated shadow module',expectedRed:expected,exitCode:run.status,sourceSha256Before:hash(source),sourceSha256After:hash(after),sourceUnchanged:source===after,variantSha256:hash(variant),temporaryGeneratedCopyRemoved:true};
  await writeFile(resolve(evidence,'recall-rag-counterfactual-result.json'),JSON.stringify(result,null,2)+'\n');
  if(!expected||source!==after)throw new Error('Counterfactual did not prove the identity guard or app source changed');
  console.log(JSON.stringify(result));
}finally{await rm(tmp,{recursive:true,force:true});}

/** Synthetic route integration: no deployment or live model/provider calls. */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createHash } from 'node:crypto';
import { spawnSync } from 'node:child_process';

if (!process.version.startsWith('v22.')) throw new Error('Use supported Node 22.');
const folder = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(folder, '../../../..');
const tests = [
  'server/routes/ana-ri/__tests__/stream-project-private-access.pglite.test.ts',
  'server/routes/chat/__tests__/send-message-private-project.test.ts',
  'server/routes/ana-ri/__tests__/stream-read-delivery.test.ts',
  'server/routes/c2c/__tests__/vault-catalog-source-review.test.ts',
  'server/routes/c2c/__tests__/project-vault-parent-access.pglite.integration.test.ts',
  'server/routes/c2c/__tests__/project-vault-search-tenant-scope.test.ts',
  'server/services/ana/__tests__/read-delivery-executor.test.ts',
  'server/routes/c2c/__tests__/projects-sources-processing.test.ts',
];
const sources = [
  'server/routes/c2c/project-vault.ts',
  'server/routes/c2c/projects.ts',
  'server/routes/ana-ri/stream.ts',
  'server/routes/chat/send-message.ts',
  'server/services/ana/AnaToolExecutor.ts',
  'server/routes/c2c/project-route-access.ts',
  'server/services/ana/catalog-scope.ts',
  'server/services/ana/document-catalog-tools.ts',
  'server/services/ana/read-receipts.ts',
  'server/services/ana/source-read-receipt.ts',
  'server/services/ana/source-context-admission.ts',
  'server/services/ana/step-presentation.ts',
  'server/services/ana-session-bootstrap.ts',
  'server/services/vault/vault-search.ts',
  'server/services/c2c/current-program-access.ts',
  'server/services/vault/document-catalog.service.ts',
  'server/services/vault/document-catalog-governance.service.ts',
  'server/services/clinical-regulatory-evidence/evidence-spine.service.ts',
  'server/services/ana/__tests__/support/read-delivery-vault.ts',
  'server/services/ana/__tests__/support/source-read-tool-fixture.ts',
];
const selected = [...new Set([...sources, ...tests])].sort();
const bindings = () => Object.fromEntries(selected.map(file => [file,
  createHash('sha256').update(fs.readFileSync(path.join(root, file))).digest('hex'),
]));
const before = bindings();
const startedAt = new Date().toISOString();
const log = path.join(folder, 'routes-focused-final.log');
const fd = fs.openSync(log, 'w');
let result;
try {
  result = spawnSync(process.execPath, ['node_modules/vitest/vitest.mjs', 'run', ...tests, '--reporter=verbose'],
    { cwd: root, env: { ...process.env, SKIP_DB_STARTUP_TEST: 'true' }, stdio: ['ignore', fd, fd] });
} finally { fs.closeSync(fd); }
const after = bindings();
const changed = selected.filter(file => before[file] !== after[file]);
const record = {
  scope: 'selected route, host handoff, and synthetic fixture integration',
  limitation: 'Selected source bindings, not an exhaustive imported graph; whole integration proof is lead-owned. PGlite is not a PostgreSQL runtime-role qualification.',
  startedAt, finishedAt: new Date().toISOString(), node: process.version,
  tests, before, after, changed, exitCode: result.status, signal: result.signal,
  passed: result.status === 0 && changed.length === 0,
};
fs.writeFileSync(path.join(folder, 'routes-focused-final.json'), JSON.stringify(record, null, 2) + '\n');
console.log(JSON.stringify({ tests: tests.length, bindings: selected.length, changed, exitCode: result.status, passed: record.passed }));
process.exitCode = record.passed ? 0 : 1;

/* Export-level parity proof for the two literal fixture constructor refactors.
 * This script only evaluates fixture modules with crypto and structuredClone. */
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const crypto = require('node:crypto');
const ts = require('typescript');
const root = path.resolve(__dirname, '../../../..');
const basePath = 'server/services/vault/__tests__/fixtures/scientific-source-facts.ts';
const heldoutPath = 'server/services/vault/__tests__/fixtures/scientific-source-facts-heldout.ts';
const modules = new Map();
function load(relativePath) {
  if (modules.has(relativePath)) return modules.get(relativePath);
  const exported = {};
  modules.set(relativePath, exported);
  const source = fs.readFileSync(path.join(root, relativePath), 'utf8');
  const compiled = ts.transpileModule(source, { compilerOptions: { target: ts.ScriptTarget.ES2022, module: ts.ModuleKind.CommonJS } }).outputText;
  vm.runInNewContext(compiled, {
    exports: exported,
    structuredClone,
    require(name) {
      if (name === 'node:crypto') return crypto;
      if (name === './scientific-source-facts') return load(basePath);
      throw new Error(`Unexpected fixture dependency: ${name}`);
    },
  }, { filename: relativePath });
  return exported;
}
const corpora = [
  { path: basePath, values: load(basePath).scientificSourceFactFixtures },
  { path: heldoutPath, values: load(heldoutPath).heldOutScientificSourceFactFixtures },
];
const result = corpora.map(corpus => ({ path: corpus.path, count: corpus.values.length,
  exportedCorpusSha256: crypto.createHash('sha256').update(JSON.stringify(corpus.values)).digest('hex'),
  sourceSha256: crypto.createHash('sha256').update(fs.readFileSync(path.join(root, corpus.path))).digest('hex'),
}));
process.stdout.write(JSON.stringify(result, null, 2) + '\n');
